define([],function(){var a={};return a.convert=function(a){a=a.slice(0);for(var b=0,c=0;c<a.length;c++)b+=a[c];if(b)for(c=0;c<a.length;c++)a[c]=Math.round(a[c]/b*100);return a},a.percentaxis=function(){return[{ticks:{min:0,max:100,callback:function(a){return a+"%"}}}]},a.percentlabels=function(){return[{ticks:{callback:function(a){return a.length>=52?a.substr(0,50)+"...":a}}}]},a.getpixelheight=function(a){return 60*a+60},a});